    """Finds the shortest path in a weighted directed graph using the Bellman-Ford algorithm."""

    # Initialize distances from start to all other nodes as infinity
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    predecessor = {node: None for node in graph}

    # Relax edges up to (V - 1) times, where V is the number of vertices
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessor[neighbor] = node

    # Check for negative-weight cycles
